# >>> STATIC
_static_displaymode() {
    cat <<-'ARGCEOF'
	0	statistics (default)
	1	stripchart without latency information
	2	stripchart with latency information
ARGCEOF
}

_static_order() {
    cat <<-'ARGCEOF'
	L	Loss ratio
	D	Dropped packets
	R	Received packets
	S	Sent Packets
	N	Newest RTT(ms)
	B	Min/Best RTT(ms)
	A	Average RTT(ms)
	W	Max/Worst RTT(ms)
	V	Standard Deviation
	G	Geometric Mean
	J	Current Jitter
	M	Jitter Mean/Avg
	X	Worst Jitter
	I	Interarrival Jitter
ARGCEOF
}

_static_ipinfo() {
    cat <<-'ARGCEOF'
	0	display AS number (equivalent to -z)
	1	display IP prefix
	2	display country code of the origin AS
	3	display RIR (ripencc, arin, ...)
	4	display the allocation date of the IP prefix
ARGCEOF
}
# <<< STATIC

# >>> CHOICES
_choice_interface() {
    if command -v ip >/dev/null 2>&1; then
        ip -o link show 2>/dev/null | gawk -F': ' '{ sub(/@.*/, "", $2); print $2 }'
        return 0
    fi
    if [[ -d /sys/class/net ]]; then
        find /sys/class/net -mindepth 1 -maxdepth 1 | sed 's|.*/||'
    elif command -v ifconfig >/dev/null 2>&1; then
        ifconfig -l 2>/dev/null | tr ' ' '\n'
    fi
}
# <<< CHOICES

command eval "$(argc --argc-eval "$0" "$@")"
